import {runTimeStudy,chartBars} from './time-engine.mjs';
import {parseStudyCSV} from './comparison-engine.mjs';
import {clock} from './engine.mjs';
let report=null,loading=false,error='',cellId='',phase='check',metric='net',tradeIndex=0,bars=null,busy=false,verification='',render=()=>{},notify=()=>{};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n),pct=n=>n===null?'—':n.toFixed(1)+'%',time=t=>clock(t).hm+' ET',date=t=>clock(t).day+' '+time(t),num=n=>Number.isFinite(n)?n.toFixed(2):'—';
const digest=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))).map(b=>b.toString(16).padStart(2,'0')).join('');
const cell=()=>report?.cells.find(c=>c.id===cellId),model=id=>report.models.find(m=>m.id===id),periodDays=()=>phase==='development'?report.config.developmentDays:phase==='fresh'?report.config.freshDays:report.config.checkDays;
const selectedTrades=()=>cell()?.trades.filter(t=>periodDays().includes(t.day))||[];
const label=c=>`${model(c.model).name} · ${c.timeframe}m · ${c.windowName}`;
function familyReference(id){const qualified=report.selection.families.find(f=>f.model===id)?.cellId;return {qualified:!!qualified,cell:report.cells.find(c=>c.id===qualified)||report.cells.filter(c=>c.model===id).sort((a,b)=>b.development.trades-a.development.trades||a.id.localeCompare(b.id))[0]};}
export async function loadTimeResearch(redraw,toast){render=redraw;notify=toast;if(report||loading||error)return;loading=true;try{const r=await fetch('time-study/report.json',{cache:'no-store'});if(!r.ok)throw Error('Timeframe research could not be loaded.');report=await r.json();cellId=report.selection.cellId||report.cells[0].id;}catch(e){error=e.message;}loading=false;render();}
async function loadBars(){if(bars)return bars;const r=await fetch(report.input.file,{cache:'no-store'});if(!r.ok)throw Error('Market data could not be loaded.');const text=await r.text();if(await digest(text)!==report.input.sha256)throw Error('Historical input checksum mismatch.');bars=parseStudyCSV(text);return bars;}
function numberCard(label,value,sub){return `<div class="metric"><div class="metric-top">${label}</div><div class="metric-value">${value}</div><div class="metric-sub">${sub}</div></div>`;}
function findings(){const choice=report.cells.find(c=>c.id===report.selection.cellId);return `<section class="panel strategy-study"><div class="eyebrow">SELECT EARLIER / CHECK LATER</div><div class="study-verdict"><div><span class="eyebrow">DEVELOPMENT-SELECTED RESEARCH CANDIDATE</span><h2>${choice?esc(label(choice)):'No qualifying candidate'}</h2><p>${choice?`${choice.start}–${choice.end} New York · strongest earlier average realized R among ${report.selection.eligibleCount} eligible cells.`:'No variant passed the preset sample-size, profit and cost-stress filters.'}</p></div><div><h3>No perfect setup was established</h3><p>${choice?`Later check: ${choice.check.wins}/${choice.check.trades} net winners, ${money(choice.check.net)}. Newly added dates: ${choice.fresh.wins}/${choice.fresh.trades}, ${money(choice.fresh.net)}. Small samples and a losing new-date trade limit the conclusion.`:'A high historical hit rate on a few examples would not justify a performance claim.'}</p></div></div>${choice?`<div class="metrics">${numberCard('Earlier / development',pct(choice.development.hitRate),choice.development.wins+'/'+choice.development.trades+' winners · '+money(choice.development.net))}${numberCard('Later / chronological check',pct(choice.check.hitRate),choice.check.wins+'/'+choice.check.trades+' winners · '+money(choice.check.net))}${numberCard('New dates / Nov 12–13',pct(choice.fresh.hitRate),choice.fresh.wins+'/'+choice.fresh.trades+' winners · '+money(choice.fresh.net))}${numberCard('Later doubled-cost result',money(choice.stressCheck.net),'Costs rerun, not just subtracted')}</div>`:''}<div class="notice"><strong>Effectiveness is not the highest hit rate.</strong> Selection requires at least 10 earlier trades, positive earlier net P&L and average R, and positive earlier P&L under doubled costs. It then ranks average realized R per trade. Later results do not choose the candidate. There are 54 experiments, so selection bias remains.</div><details><summary>What the sources and results actually support</summary><p>ICT is a framework rather than one mechanical rule. This study specifies one sweep → structure-shift → gap-retest subset. FVG and IFVG are different entry models. Head-and-shoulders needs delayed pivot confirmation; drawing the shoulders retrospectively would give the tester information unavailable at entry.</p><p>Liquidity here is a price-level sweep proxy. OHLC cannot establish where stop orders rested or why a participant traded. These patterns generate qualified candidates under the written rules, not guaranteed winners or trained-AI probabilities.</p><p>All cells use fixed 2R price targets and the same $100 trade budget, $300 daily entry budget, maximum 3 MNQ, assumed $1.24 round-trip fee per contract and one adverse tick on entry/stop/market exits. Larger-chart stops may disqualify even one contract. The model has no account-specific trailing-drawdown or margin test.</p><p>The chronological check includes Nov 9–11, previously viewed in this project. Nov 12–13 are new additions, but all testing is retrospective. No untouched prospective performance claim is made.</p></details></section>`;}
function familyTable(){return `<section class="panel"><div class="panel-heading"><div><h2>Research comparison by family</h2><p>Eligible rows use the best earlier qualifying cell. Other rows use the largest earlier trade sample only, clearly marked as references.</p></div></div><div class="table-wrap"><table><thead><tr><th>Family / exact variant</th><th>Selection status</th><th>Earlier hit / trades</th><th>Later hit / trades</th><th>Later net P&L</th><th>New dates net</th><th>Inspect</th></tr></thead><tbody>${report.models.map(m=>{const {cell:c,qualified}=familyReference(m.id);return `<tr><td>${esc(m.name)}<small class="time-small">${c.timeframe}m · ${c.windowName} · ${c.start}–${c.end}</small></td><td><span class="tag ${qualified?'':'amber'}">${qualified?'EARLIER FILTERS PASSED':'REFERENCE ONLY'}</span></td><td>${pct(c.development.hitRate)} · ${c.development.trades}</td><td>${pct(c.check.hitRate)} · ${c.check.trades}</td><td class="${c.check.net<0?'negative':'positive'}">${money(c.check.net)}</td><td class="${c.fresh.net<0?'negative':'positive'}">${money(c.fresh.net)}</td><td><button class="link-button" data-time-cell="${c.id}">Proof ↗</button></td></tr>`;}).join('')}</tbody></table></div><p class="study-footnote">No-trade cells show no hit-rate estimate. Reference-only rows did not meet the 10-trade/profit/stress criteria and are not endorsements. Different cells are separate experiments; do not add their results as a portfolio.</p></section>`;}

function conclusions(){const get=id=>familyReference(id).cell,f=get('fvg'),inv=get('ifvg'),liq=get('liquidity');return `<section class="panel"><h2>What this research found</h2><div class="three-cols" style="margin-top:22px"><div><h3>FVG: a candidate, not a proven edge</h3><p>The earlier-selected ${f.timeframe}m ${f.windowName.toLowerCase()} variant held a ${pct(f.check.hitRate)} hit rate on ${f.check.trades} later trades, but its ${f.fresh.trades} newly added-date trade lost ${money(-f.fresh.net)}. More untouched sessions are needed.</p></div><div><h3>IFVG: payoff matters as much as hit rate</h3><p>The selected ${inv.timeframe}m ${inv.windowName.toLowerCase()} variant had ${inv.check.wins}/${inv.check.trades} later winners (${pct(inv.check.hitRate)}) and ${money(inv.check.net)} net. Its later average realized R was ${inv.check.averageR.toFixed(3)}R; cash profit and average risk-normalized performance tell different stories when position sizes vary.</p></div><div><h3>Liquidity: earlier profit did not persist</h3><p>The selected ${liq.timeframe}m ${liq.windowName.toLowerCase()} sweep variant fell to ${pct(liq.check.hitRate)} on ${liq.check.trades} later trades and ${money(liq.check.net)}. This is a direct counterexample to assuming an earlier positive backtest guarantees effectiveness.</p></div></div><div class="notice">ORB, the strict ICT subset and head-and-shoulders did not pass the earlier minimum-sample/profit/stress selection. Their reference rows are observations under these risk and pattern rules, not evidence that the entire strategy family works or fails.</div></section>`;}

function matrix(){return `<section class="panel"><div class="panel-heading"><div><h2>Timeframe × entry-window matrix</h2><p>Click any result to inspect its rules, full trade log, daily results and chart.</p></div></div><div class="settings"><label>Research period<select id="timePhase"><option value="development" ${phase==='development'?'selected':''}>Earlier · Oct 22–Nov 6 · 11 sessions</option><option value="check" ${phase==='check'?'selected':''}>Later check · Nov 9–13 · 5 sessions</option><option value="fresh" ${phase==='fresh'?'selected':''}>Newly added · Nov 12–13 · 2 sessions</option></select></label><label>Cell value<select id="timeMetric"><option value="net" ${metric==='net'?'selected':''}>Net simulated P&L</option><option value="hitRate" ${metric==='hitRate'?'selected':''}>Net hit rate</option><option value="averageR" ${metric==='averageR'?'selected':''}>Average realized R / trade</option></select></label><div class="notice" style="margin:0;font-size:9px">Morning 09:45–11:30<br>Midday 11:30–14:00<br>Afternoon 14:00–15:30 · New York</div></div><div class="table-wrap time-matrix"><table><thead><tr><th rowspan="2">Strategy</th>${report.config.timeframes.map(tf=>`<th colspan="3">${tf}-minute chart</th>`).join('')}</tr><tr>${report.config.timeframes.flatMap(()=>report.config.windows.map(w=>`<th>${w.name}</th>`)).join('')}</tr></thead><tbody>${report.models.map(m=>`<tr><th>${esc(m.name)}</th>${report.config.timeframes.flatMap(tf=>report.config.windows.map(w=>{const c=report.cells.find(c=>c.model===m.id&&c.timeframe===tf&&c.window===w.id),s=c[phase],val=metric==='net'?money(s.net):metric==='hitRate'?pct(s.hitRate):s.averageR===null?'—':s.averageR.toFixed(2)+'R';return `<td><button class="matrix-cell ${s.trades?(s.net>=0?'gain':'loss'):'none'} ${cellId===c.id?'chosen':''}" data-time-cell="${c.id}" aria-pressed="${cellId===c.id}"><strong>${s.trades?val:'No trades'}</strong><small>${s.wins}/${s.trades} winners${s.trades<10?' · small n':''}</small></button></td>`;})).join('')}</tr>`).join('')}</tbody></table></div><p class="study-footnote">Color reflects net profit/loss, not predictive confidence. Each cell is an independent rule/timeframe/window experiment. Chart lookbacks measured in bars cover different clock durations. The ORB range stays 09:30–09:44 and only its first daily breakout attempt counts; later ORB windows can correctly be empty.</p></section>`;}
function setupChart(){const c=cell(),trades=selectedTrades(),t=trades[tradeIndex]||trades[0];if(!t)return '<div class="empty">No executed trade in this cell and period. Inspect the rejected signals below.</div>';if(!bars)return '<div class="empty"><button class="button" id="timeLoadChart">Load historical setup chart ↗</button></div>';const dayBars=bars.filter(b=>clock(b.t).day===t.day),pivots=t.context.pivots||[],start=Math.min(t.confirmedAt-20*c.timeframe*60000,...pivots.map(p=>p.t)),end=t.exitTime+5*c.timeframe*60000,bs=chartBars(dayBars,c.timeframe).filter(b=>b.t>=start&&b.t<=end);if(!bs.length)return '';const w=900,h=290,values=bs.flatMap(b=>[b.h,b.l]).concat([t.entry,t.stop,t.target]),hi=Math.max(...values),lo=Math.min(...values),span=hi-lo||1,spanT=Math.max(c.timeframe*60000,bs.at(-1).t-bs[0].t+c.timeframe*60000),x=ts=>18+(ts-bs[0].t)/spanT*790,y=v=>23+(hi-v)/span*220,bw=790/(bs.length+1);let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Historical ${c.timeframe}-minute MNQ candles showing a completed setup and simulated trade">`;for(let k=0;k<5;k++){const v=hi-span*k/4;svg+=`<path d="M18 ${y(v)}H812" stroke="#e7ecdf"/><text x="824" y="${y(v)+4}" font-size="9" fill="#8c9c7f">${v.toFixed(2)}</text>`;}if(t.context.gap){const g=t.context.gap,left=Math.max(18,x(g.born));svg+=`<rect x="${left}" width="${Math.max(0,812-left)}" y="${y(g.hi)}" height="${Math.max(1,y(g.lo)-y(g.hi))}" fill="#d5e3bf" opacity=".5"/>`;}
for(const b of bs){const color=b.c>=b.o?'#adbf95':'#365d42',cx=x(b.t)+bw/2;svg+=`<path d="M${cx} ${y(b.h)}V${y(b.l)}" stroke="${color}"/><rect x="${cx-bw*.25}" y="${y(Math.max(b.o,b.c))}" width="${Math.max(1,bw*.5)}" height="${Math.max(1,Math.abs(y(b.o)-y(b.c)))}" fill="${color}"/>`;}
for(const [label,v,col] of [['ENTRY',t.entry,'#477957'],['STOP',t.stop,'#b06c5a'],['TARGET',t.target,'#78954e']])svg+=`<path d="M18 ${y(v)}H812" stroke="${col}" stroke-dasharray="5 4"/><text x="22" y="${y(v)-4}" font-size="8" fill="${col}">${label} ${v.toFixed(2)}</text>`;
for(const [label,ts] of [['CONFIRMED / ENTRY',t.entryTime],['EXIT',t.exitTime]])svg+=`<path d="M${x(ts)} 20V247" stroke="${label==='EXIT'?'#b48b57':'#65874d'}" stroke-dasharray="3 4"/><text x="${Math.min(630,Math.max(22,x(ts)+3))}" y="${label==='EXIT'?27:12}" font-size="9" fill="#71875f">${label} ${time(ts)}</text>`;for(const p of pivots)svg+=`<circle cx="${x(p.t)+bw/2}" cy="${y(p.price)}" r="4" fill="#9b7bba"/><text x="${x(p.t)+bw/2}" y="${y(p.price)-8}" fill="#8e729d" font-size="8" text-anchor="middle">${p.kind}</text>`;
for(let i=0;i<bs.length;i+=Math.max(1,Math.floor(bs.length/6)))svg+=`<text x="${x(bs[i].t)}" y="273" font-size="9" fill="#8d9c7f">${clock(bs[i].t).hm}</text>`;return svg+'</svg>'+`<p>${c.timeframe}m signal candles shown; entries and exits use original 1m data. ${t.side===1?'Long':'Short'} ${t.qty} MNQ · ${t.reason} · <strong>${money(t.pnl)} net</strong>. Historical illustration, not a perfect or predicted winner.</p>`;}
function audit(){const c=cell(),m=model(c.model),s=c[phase],trades=selectedTrades(),signals=c.signals.filter(s=>periodDays().includes(s.day)),t=trades[tradeIndex]||trades[0];return `<section class="panel" id="timeAudit"><div class="panel-heading"><div><div class="eyebrow">INSPECT THE EXACT EXPERIMENT</div><h2 style="margin-top:8px">${esc(label(c))}</h2><p>${c.start}–${c.end} New York · ${phase==='check'?'later check':phase==='fresh'?'new dates':'earlier development'}</p></div><a class="button small" href="time-study/report.json" download>↓ Full audit report</a></div><label>Experiment<select id="timeCell">${report.cells.map(x=>`<option value="${x.id}" ${cellId===x.id?'selected':''}>${esc(label(x))}</option>`).join('')}</select></label><div class="notice"><strong>${esc(m.fullName)}.</strong> ${esc(m.rules)} All trades use fixed 2R price targets; a later session-close exit can realize a different payoff.</div><div class="metrics">${numberCard('Net hit rate',pct(s.hitRate),s.wins+'/'+s.trades+' winners')}${numberCard('Net simulated P&L',money(s.net),'After configured fees/slippage')}${numberCard('Average realized R',s.averageR===null?'—':s.averageR.toFixed(3)+'R','Net per trade / its planned risk')}${numberCard('Closed-trade drawdown',money(s.maxDrawdown),'Not intratrade equity drawdown')}</div><p class="study-footnote">95% descriptive hit-rate interval: ${s.hitInterval?s.hitInterval.map(n=>n.toFixed(1)+'%').join('–'):'not available without trades'}. This interval is not adjusted for searching 54 cells or dependent trades.</p>${trades.length?`<label>Historical setup<select id="timeTrade">${trades.map((t,i)=>`<option value="${i}" ${tradeIndex===i?'selected':''}>${date(t.entryTime)} · ${t.side===1?'Long':'Short'} · ${money(t.pnl)} · ${t.reason}</option>`).join('')}</select></label>`:''}<div class="evidence-chart">${setupChart()}</div>${t?`<div class="two-cols"><div><h3>Why this setup qualified at entry</h3><ul class="checklist"><li class="pass">Signal chart candle completed</li><li class="pass">Written pattern conditions satisfied</li><li class="pass">Entry minute and window valid</li><li class="pass">Position size fits configured budget</li><li class="pass">Invalidation and 2R target defined</li></ul></div><div><h3>Decision-time evidence</h3><p>Confirmed ${date(t.confirmedAt)}. Entry ${num(t.entry)}, stop ${num(t.stop)}, target ${num(t.target)}. Planned risk including configured fees and stop slippage: ${money(t.risk)}.</p><p>${t.context.gap?'Gap '+num(t.context.gap.lo)+'–'+num(t.context.gap.hi)+', formed '+time(t.context.gap.born)+'. ':''}${t.context.pivots?'All five pivots were confirmed by '+time(t.confirmedAt)+', with two-chart-bar confirmation delay. ':''}${t.context.sweep?'Sweep '+time(t.context.sweep.sweepAt)+' → structure shift '+time(t.context.sweep.shiftAt)+'. ':''}${t.context.priorLow?'Prior low/high: '+num(t.context.priorLow)+' / '+num(t.context.priorHigh)+'. ':''}</p><p>The checklist explains selection; it is not a win probability. This example’s outcome was known when selected for display.</p></div></div>`:''}<details><summary>Daily evidence across all 16 sessions</summary><div class="table-wrap"><table><thead><tr><th>Session</th><th>Period</th><th>Signals</th><th>Trades</th><th>Wins</th><th>Hit rate</th><th>Net P&L</th></tr></thead><tbody>${c.daily.map(d=>`<tr><td>${d.day}</td><td>${d.phase}${report.config.freshDays.includes(d.day)?' / new':''}</td><td>${d.signals}</td><td>${d.trades}</td><td>${d.wins}</td><td>${pct(d.hitRate)}</td><td class="${d.net<0?'negative':'positive'}">${money(d.net)}</td></tr>`).join('')}</tbody></table></div></details><details><summary>All ${trades.length} executed trades in the selected period</summary><div class="table-wrap"><table><thead><tr><th>Entry / ET</th><th>Side / size</th><th>Entry</th><th>Stop</th><th>Target</th><th>Exit / ET</th><th>Exit price</th><th>Net P&L</th></tr></thead><tbody>${trades.map(t=>`<tr><td>${date(t.entryTime)}</td><td>${t.side===1?'Long':'Short'} · ${t.qty}</td><td>${num(t.entry)}</td><td>${num(t.stop)}</td><td>${num(t.target)}</td><td>${date(t.exitTime)} · ${t.reason}</td><td>${num(t.exit)}</td><td>${money(t.pnl)}</td></tr>`).join('')}</tbody></table></div></details><details><summary>Detected and rejected candidates (${signals.length})</summary><div class="table-wrap"><table><thead><tr><th>Confirmed / ET</th><th>Status</th><th>Reason</th></tr></thead><tbody>${signals.map(s=>`<tr><td>${date(s.confirmedAt)}</td><td>${s.status}</td><td>${esc(s.rejection||'Passed written entry rules')}</td></tr>`).join('')}</tbody></table></div></details><div class="actions" style="margin-top:20px"><button class="button primary" id="timeReproduce" ${busy?'disabled':''}>${busy?'Replaying 54 experiments…':'↻ Reproduce all 54 experiments'}</button><a class="button" href="time-study/mnq.csv" download>↓ Source candles</a><a class="button" href="time-study/frozen.json" download>↓ Frozen method</a></div><p id="timeVerification" role="status">${esc(verification)}</p></section>`;}
function notes(){return `<section class="panel"><div class="panel-heading"><h2>Strategy blueprints & research sources</h2><span class="tag gray">REVIEWED NOV 15, 2026</span></div>${report.models.map(m=>`<article class="source-card"><h3>${esc(m.name)} · ${esc(m.fullName)}</h3><p>${esc(m.rules)}</p></article>`).join('')}<div class="section-label">SOURCES / WHAT WAS REVIEWED</div>${report.research.map(s=>`<article class="source-card"><a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><p>${esc(s.finding)}</p></article>`).join('')}<details><summary>Data provenance, limitations and reproducibility</summary><p>${esc(report.freeze.selection)}</p><ul>${report.limits.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>Source: Yahoo Finance chart API, MNQ=F. ${report.input.rows.toLocaleString()} valid source minutes. October 30 was excluded for incomplete regular-session coverage. No missing candles were filled in.</p><p>CSV SHA-256<br><code class="hash">${report.input.sha256}</code></p>${report.engines.map(f=>`<p>${f.file}<br><code class="hash">${f.sha256}</code></p>`).join('')}<div class="actions"><a class="button small" href="time-study/source-manifest.json" download>↓ Source retrieval manifest</a><a class="button small" href="time-engine.mjs" download>↓ Detector and execution code</a></div></details></section>`;}
export function timeResearchPage(){return `<div class="page-title"><div><div class="eyebrow">TIMEFRAME & SESSION RESEARCH</div><h1>When does the setup hold up?</h1><p>ORB, ICT-style, FVG, IFVG, head-and-shoulders and liquidity sweeps—compare defined setups across chart times and entry windows.</p></div></div>${!report?`<section class="panel"><p>${esc(error||'Loading the complete timeframe study…')}</p></section>`:`<div class="metrics">${numberCard('Explicit experiments','54','6 models × 3 charts × 3 windows')}${numberCard('Complete sessions','16','Oct 22–Nov 13; incomplete Oct 30 excluded')}${numberCard('Signal chart timeframes','1m / 3m / 5m','Executions resolved from original 1m bars')}${numberCard('Period separation','11 → 5','Earlier selection → later check')}</div>`+findings()+familyTable()+conclusions()+matrix()+audit()+notes()}`;}
export function bindTimeResearch(){if(!report)return;const choose=id=>{cellId=id;tradeIndex=0;render();document.getElementById('timeAudit')?.scrollIntoView({behavior:'smooth',block:'start'});};document.querySelectorAll('[data-time-cell]').forEach(b=>b.onclick=()=>choose(b.dataset.timeCell));document.getElementById('timeCell')?.addEventListener('change',e=>choose(e.target.value));document.getElementById('timePhase')?.addEventListener('change',e=>{phase=e.target.value;tradeIndex=0;render();});document.getElementById('timeMetric')?.addEventListener('change',e=>{metric=e.target.value;render();});document.getElementById('timeTrade')?.addEventListener('change',e=>{tradeIndex=+e.target.value;render();});document.getElementById('timeLoadChart')?.addEventListener('click',async()=>{try{await loadBars();render();}catch(e){notify(e.message);}});document.getElementById('timeReproduce')?.addEventListener('click',async()=>{busy=true;verification='Checking data and all engine hashes…';render();try{for(const f of report.engines){const r=await fetch(f.file,{cache:'no-store'});if(!r.ok||await digest(await r.text())!==f.sha256)throw Error('Engine checksum mismatch: '+f.file);}if(await digest(JSON.stringify(report.config))!==report.freeze.configSha256)throw Error('Frozen configuration checksum mismatch.');const data=await loadBars();verification='Replaying the earlier selection, later checks and doubled-cost experiments…';render();await new Promise(r=>setTimeout(r,0));const actual=runTimeStudy(data,report.config);if(JSON.stringify(actual)!==JSON.stringify({config:report.config,models:report.models,selection:report.selection,cells:report.cells}))throw Error('The recomputed report differs from the saved evidence.');verification='✓ Reproduced exactly: 54 baseline/cost-stress cells, earlier-only selection, later checks, all trades, signals and daily metrics. Input, code and configuration hashes match.';notify('Timeframe study reproduced exactly');}catch(e){verification='Verification failed: '+e.message;}busy=false;render();});}
